 "content": "from collections import deque


def transform(grid):
    """Recolor every orthogonally connected zero component of size > 1 as 8."""
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    seen = set()
    for r in range(height):
        for c in range(width):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            component = []
            queue = deque([(r, c)])
            seen.add((r, c))
            while queue:
                rr, cc = queue.popleft()
                component.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < height and 0 <= nc < width and
                            grid[nr][nc] == 0 and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        queue.append((nr, nc))
            if len(component) > 1:
                for rr, cc in component:
                    out[rr][cc] = 8
    return out
